\begin{tikzpicture}[font=\sffamily, thick, >=stealth]

  % Axes
  \draw[->] (0,0) coordinate (origin) -- (7,0) node[anchor=north] {Progress of reaction};
  \draw[->] (0,0) -- (0,6.5) node[anchor=east] {Energy};

  % Levels
  \coordinate (R) at (0.8, 2.0);
  \coordinate (P) at (6.2, 0.8);

  \draw (R) -- ++(1.2,0) node[midway, above] {};
  \draw (P) -- ++(-1.2,0) node[midway, above] {};

  % Curves
  % Uncatalysed peak (higher)
  \coordinate (PeakU) at (3.5, 5.2);
  \draw[solid] (R) to[out=10, in=170] (PeakU) to[out=-10, in=160] (P);

  % Catalysed peak (lower)
  \coordinate (PeakC) at (3.5, 3.8);
  \draw[dashed] (R) to[out=25, in=155] (PeakC) to[out=-25, in=145] (P);

  % Labels for reactants and products
  \node[anchor=east] at (R) {Reactants};
  \node[anchor=west] at (P) {Products};

  % Labels for curves
  \node[anchor=south] at (3.5, 5.2) {without catalyst};
  \node[anchor=south, yshift=2mm] at (3.5, 3.8) {with catalyst};

  % Double-headed arrow for Ea (from reactants to uncatalysed peak)
  \draw[<->] (2.2, 2.0) -- (2.2, 5.2) node[midway, right] {$E_a$};

  % Arrow for Delta H (from reactants level down to products level)
  \draw[<->] (5.0, 2.0) -- (5.0, 0.8) node[midway, right] {$\Delta H$};

  % Caption
  \node[anchor=north] at (3.5, -0.8) {Fig. 4.1};

\end{tikzpicture}
